item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across runs."
        }
      ],
      "instrument_review": "MESA 14 concerns whether repeated testing occurred; MESA 16 concerns evidence about score variation. Both remain unresolved here."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "Without repeated results, stability is unknown; the absence of testing does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14 would be No because non-repetition is explicit. MESA 16 lacks evidence supporting stability."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same stated conditions occurred."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 supports that repetition was tested. MESA 16 supports stability for the observed runs under the stated definition and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing occurred regardless of whether its results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 would be Yes because testing occurred. The findings relevant to MESA 16 contradict stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation does not establish that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score stability."
        }
      ],
      "instrument_review": "Installation instructions concern availability and reproducibility under MESA 22. They do not resolve repeated testing under MESA 14 or score variation under MESA 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25 support the stated narrow intended use. Under MESA 9 and 20, grid-only evidence does not establish broader abilities."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Declaring a broad intended use does not supply evidence for cross-domain general intelligence."
        }
      ],
      "instrument_review": "MESA 2 identifies the broad intended use, but MESA 9 and 20 reveal insufficient coverage and evidence for it. Under MESA 25, a general-intelligence conclusion would exceed the supplied findings."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks and reported difference interval support better correctness with A in the studied workshop."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not itself establish improved workplace safety."
        }
      ],
      "instrument_review": "MESA 20 distinguishes initial test scores from later evidence on actual decisions. The trial supports the workshop-specific correctness use, with uncertainty reported under MESA 16. MESA 25 limits conclusions to measured outcomes and studied conditions."
    }
  ],
  "closing_note": "No instruction clarification was needed. Missing evidence was treated as Not established, and evidence that testing occurred was distinguished from evidence of favourable results."
}
